body:
`NavigationProvider` defaults `context` to `'home'`. On `/apps/:appName/*` routes this will render the Home navigation until `ConsoleLayout`'s effect flips the context, causing a visible sidebar flicker and briefly wrong links. Consider initializing the context from the current route (or allowing an initialContext param) so the first render matches the active route.
```suggestion
function getInitialNavigationState(): {
  context: NavigationContextType;
  currentAppName?: string;
} {
  if (typeof window === 'undefined') {
    return { context: 'home' };
  }

  const match = window.location.pathname.match(/^\/apps\/([^/]+)(?:\/.*)?$/);

  if (!match) {
    return { context: 'home' };
  }

  return {
    context: 'app',
    currentAppName: decodeURIComponent(match[1]),
  };
}

export function NavigationProvider({ children }: NavigationProviderProps) {
  const [initialNavigationState] = useState(getInitialNavigationState);
  const [context, setContext] = useState<NavigationContextType>(initialNavigationState.context);
  const [currentAppName, setCurrentAppName] = useState<string | undefined>(
    initialNavigationState.currentAppName
  );
```
